        result=subprocess.run(['python3','-I',str(extractor),str(prior/'source.tar.gz'),str(prior/'source'),'--verify'],stdin=subprocess.DEVNULL,stdout=subprocess.PIPE,stderr=subprocess.PIPE,timeout=60)
        if result.returncode or os.environ.get('NODE_OPTIONS'):raise ValueError()
