        if result.returncode:raise ValueError()
        recovery=json.loads(result.stdout)
        if recovery.get('previousStatus')!='failed-before-application-write-marker':raise ValueError()
        stage='local-directory'
        base=home/BASE_NAME;base.mkdir(mode=0o700)
        (base/'prior-preflight-stop.json').write_text(json.dumps(recovery)+'\n')
        print('RECOVERY_OK: previous attempt stopped before application writes; original files retained.',flush=True)
        start=launched+1800000;end=start+604800000
