        print('START: '+jst(start),flush=True);print('END: '+jst(end),flush=True)
        (base/'launch.json').write_text(json.dumps({'schemaVersion':1,'launchedAtMillis':launched,'startsAtMillis':start,'endsAtMillis':end,'sourceCommit':'f0bc4eb0b708f5890d2bc044e1f89b91c96abc71'})+'\n')
        stage='source-download'
